class Solution:
    def timeTaken(self, edges):
        n = len(edges) + 1
        g = [[] for _ in range(n)]
        for u, v in edges:
            g[u].append(v); g[v].append(u)
        w = lambda u, v: 2 if v % 2 == 0 else 1
        par = [-1] * n; order = []; st = [0]
        while st:
            u = st.pop(); order.append(u)
            for v in g[u]:
                if v != par[u]: par[v] = u; st.append(v)
        down = [0] * n; up = [0] * n
        for u in reversed(order):
            for v in g[u]:
                if v != par[u]: down[u] = max(down[u], down[v] + w(u, v))
        for u in order:
            b1 = b2 = -1
            for v in g[u]:
                if v == par[u]: continue
                d = down[v] + w(u, v)
                if d > b1: b2, b1 = b1, d
                elif d > b2: b2 = d
            for v in g[u]:
                if v == par[u]: continue
                d = down[v] + w(u, v)
                up[v] = max(up[u], b2 if d == b1 else b1) + w(u, v)
        return [max(down[i], up[i]) for i in range(n)]

