class Solution {
public:
    vector<int> timeTaken(vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        vector<vector<int>> g(n);
        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        auto W = [](int u, int v){ return v % 2 == 0 ? 2 : 1; };
        vector<int> par(n, -1), order, down(n, 0), up(n, 0);
        vector<int> st = {0};
        while (!st.empty()) {
            int u = st.back(); st.pop_back(); order.push_back(u);
            for (int v : g[u]) if (v != par[u]) { par[v] = u; st.push_back(v); }
        }
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            for (int v : g[u]) if (v != par[u]) down[u] = max(down[u], down[v] + W(u, v));
        }
        for (int u : order) {
            int b1 = -1, b2 = -1;
            for (int v : g[u]) {
                if (v == par[u]) continue;
                int d = down[v] + W(u, v);
                if (d > b1) { b2 = b1; b1 = d; } else if (d > b2) b2 = d;
            }
            for (int v : g[u]) {
                if (v == par[u]) continue;
                int d = down[v] + W(u, v);
                up[v] = max(up[u], (d == b1 ? b2 : b1)) + W(u, v);
            }
        }
        vector<int> res(n);
        for (int i = 0; i < n; i++) res[i] = max(down[i], up[i]);
        return res;
    }
};

