class Solution {
    public int[] timeTaken(int[][] edges) {
        int n = edges.length + 1;
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        int[] par = new int[n], down = new int[n], up = new int[n], order = new int[n];
        Arrays.fill(par, -1);
        Deque<Integer> st = new ArrayDeque<>(List.of(0));
        int idx = 0;
        while (!st.isEmpty()) {
            int u = st.pop(); order[idx++] = u;
            for (int v : g.get(u)) if (v != par[u]) { par[v] = u; st.push(v); }
        }
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            for (int v : g.get(u)) if (v != par[u]) down[u] = Math.max(down[u], down[v] + w(u, v));
        }
        for (int k = 0; k < n; k++) {
            int u = order[k], b1 = -1, b2 = -1;
            for (int v : g.get(u)) {
                if (v == par[u]) continue;
                int d = down[v] + w(u, v);
                if (d > b1) { b2 = b1; b1 = d; } else if (d > b2) b2 = d;
            }
            for (int v : g.get(u)) {
                if (v == par[u]) continue;
                int d = down[v] + w(u, v);
                up[v] = Math.max(up[u], (d == b1 ? b2 : b1)) + w(u, v);
            }
        }
        int[] res = new int[n];
        for (int i = 0; i < n; i++) res[i] = Math.max(down[i], up[i]);
        return res;
    }
    int w(int u, int v) { return v % 2 == 0 ? 2 : 1; }
}

