var timeTaken = function(edges) {
    const n = edges.length + 1;
    const g = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { g[u].push(v); g[v].push(u); }
    const w = (u, v) => v % 2 === 0 ? 2 : 1;
    const par = new Array(n).fill(-1), order = [], down = new Array(n).fill(0), up = new Array(n).fill(0);
    const st = [0];
    while (st.length) {
        const u = st.pop(); order.push(u);
        for (const v of g[u]) if (v !== par[u]) { par[v] = u; st.push(v); }
    }
    for (let i = n - 1; i >= 0; i--) {
        const u = order[i];
        for (const v of g[u]) if (v !== par[u]) down[u] = Math.max(down[u], down[v] + w(u, v));
    }
    for (const u of order) {
        let b1 = -1, b2 = -1;
        for (const v of g[u]) {
            if (v === par[u]) continue;
            const d = down[v] + w(u, v);
            if (d > b1) { b2 = b1; b1 = d; } else if (d > b2) b2 = d;
        }
        for (const v of g[u]) {
            if (v === par[u]) continue;
            const d = down[v] + w(u, v);
            up[v] = Math.max(up[u], d === b1 ? b2 : b1) + w(u, v);
        }
    }
    return down.map((d, i) => Math.max(d, up[i]));
};
